const token = $json.body.spotifyToken.replace('Bearer ', '');

return [{
  prompt: $json.body.prompt,
  spotifyToken: token,
  playlistId: $json.body.playlistId,
  uris: [],
  attempts: 0
}];

const entrada = $('Extrair Dados').first().json;
const topArtists = $json.items ? $json.items.map(a => a.name) : [];

const existingNames = [];

// Extrai os nomes das músicas que já estão na playlist para a IA ler
const existNodes = $items("Buscar Existentes");
for (const item of existNodes) {
    let tracks = item.json.items || item.json || [];
    if(!Array.isArray(tracks)) tracks = [tracks];

    for(const t of tracks) {
        const trackData = t.track || t.item || t;
        if(trackData?.name) {
            const artist = trackData.artists?.[0]?.name || "";
            existingNames.push(`${trackData.name} - ${artist}`);
        }
    }
}

return [{
  prompt: entrada.prompt,
  spotifyToken: entrada.spotifyToken,
  playlistId: entrada.playlistId,
  topArtists: topArtists,
  existingNames: existingNames,
  attempts: 0,
  allUris: []
}];

