let raw = $json.candidates[0].content.parts[0].text;
const parsed = JSON.parse(raw);

return parsed.tracks.map(t => ({
  artist: t.artist,
  track: t.track,
  album: t.album,

  // 🔥 mantém estado do loop
  attempts: $json.attempts,
  uris: $json.uris || [],
  allUris: $json.allUris || [],

  spotifyToken: $json.spotifyToken,
  playlistId: $json.playlistId
}));

const validTracks = [];

function normalize(str) {
  return (str || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9 ]/g, "")
    .trim();
}

for (const i of $items()) {
  const results = i.json.tracks?.items || [];

  const expectedName = normalize(i.json.track);
  const expectedArtist = normalize(i.json.artist);

  for (const item of results) {
    const spotifyName = normalize(item.name);
    const spotifyArtist = normalize(item.artists?.[0]?.name);

    if (
      spotifyArtist !== expectedArtist &&
      !spotifyArtist.startsWith(expectedArtist) &&
      !expectedArtist.startsWith(spotifyArtist)
    ) {
      continue;
    }

    const nameMatch =
      spotifyName.includes(expectedName) ||
      expectedName.includes(spotifyName);

    if (!nameMatch) continue;

    // 🔥 Agora exportamos a URI e uma "chave" de texto com Nome e Artista
    validTracks.push({
      uri: item.uri,
      key: `${spotifyName}-${spotifyArtist}`
    });
    break; 
  }
}

return [{
  validTracks,
  uris: validTracks.map(t => t.uri), // Mantém por compatibilidade do n8n
  spotifyToken: $items()[0].json.spotifyToken,
  playlistId: $items()[0].json.playlistId
}];

function normalize(str) {
  return (str || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9 ]/g, "")
    .trim();
}

const existingUris = new Set();
const existingKeys = new Set();

// 1. Mapear as músicas existentes buscando do nó lá do início
let allExistingItems = [];
const existNodes = $items("Buscar Existentes");
for (const item of existNodes) {
    if (item.json.items) {
        allExistingItems.push(...item.json.items);
    } else if (Array.isArray(item.json)) {
        allExistingItems.push(...item.json);
    } else {
        allExistingItems.push(item.json);
    }
}

for (const i of allExistingItems) {
  let trackData = i;
  if (i.item && typeof i.item === 'object') {
      trackData = i.item;
  } else if (i.track && typeof i.track === 'object') {
      trackData = i.track;
  }

  if (!trackData || !trackData.uri || !trackData.name) continue;

  existingUris.add(trackData.uri);
  const tName = normalize(trackData.name);
  let aName = "";
  if (trackData.artists && trackData.artists[0]) {
      aName = normalize(trackData.artists[0].name);
  }
  existingKeys.add(`${tName}-${aName}`);
}

// 2. Resgatar o estado do loop
let prev = [];
let attempts = 0;
try {
  const loopNode = $('Code in JavaScript').last();
  if (loopNode && loopNode.json) {
    prev = loopNode.json.allUris || [];
    attempts = loopNode.json.attempts || 0;
  }
} catch (e) {}

// 3. Pegar as novas músicas do nó Validar
let newOnes = [];
try {
  const validarNode = $('Validar').last();
  if (validarNode && validarNode.json) {
    newOnes = validarNode.json.validTracks || [];
  }
} catch (e) {}

// 4. O Filtro de Dupla Checagem (Proteção Máxima)
const filteredNewObjects = newOnes.filter(track => {
    const isUriDuplicate = existingUris.has(track.uri);
    const isNameDuplicate = existingKeys.has(track.key);
    return !isUriDuplicate && !isNameDuplicate;
});

const filteredNewUris = filteredNewObjects.map(t => t.uri);
const merged = [...new Set([...prev, ...filteredNewUris])];

return [{
  allUris: merged,
  uris: merged,
  spotifyToken: $('Extrair Dados').first().json.spotifyToken,
  playlistId: $('Extrair Dados').first().json.playlistId,
  attempts: attempts
}];

