const target = 5;
const maxAttempts = 2;

const merged = $json.allUris || [];

const attempts = ($json.attempts ?? 0) + 1;

const done = merged.length >= target || attempts >= maxAttempts;

return [{
  allUris: merged,
  total: merged.length,
  attempts,
  done,
  spotifyToken: $json.spotifyToken,
  playlistId: $json.playlistId
}];
